// Compare evidence-02 against evidence-01 by pixel diff and by measure JSON. Facts only.
// Writes measure/run-comparison.json. CHANGES-SINCE-RUN-1.md is generated by changes-md.mjs from that file.
import fs from 'node:fs'
import { OUT, RUN1, PNG } from './lib.mjs'
import { diffPngs } from './analyze-lib.mjs'

const rd = (p) => JSON.parse(fs.readFileSync(p, 'utf8'))
const m1 = rd(`${RUN1}/manifest.json`)
const m2 = rd(`${OUT}/manifest.json`)
const ids1 = new Set(m1.map((m) => m.id))
const ids2 = new Set(m2.map((m) => m.id))
const shared = m1.map((m) => m.id).filter((id) => ids2.has(id))
const load = (p) => PNG.sync.read(fs.readFileSync(p))

function keyed(arr, keyFn) {
  const seen = new Map()
  const out = new Map()
  for (const e of arr) {
    const k = keyFn(e)
    const n = (seen.get(k) || 0) + 1
    seen.set(k, n)
    out.set(k + '#' + n, e)
  }
  return out
}
const same = (a, b, tol = 0.05) => (typeof a === 'number' && typeof b === 'number' ? Math.abs(a - b) <= tol : JSON.stringify(a) === JSON.stringify(b))

const out = { generated: new Date().toISOString(), states: {}, onlyInRun1: [...ids1].filter((i) => !ids2.has(i)), onlyInRun2: [...ids2].filter((i) => !ids1.has(i)) }
fs.mkdirSync(`${OUT}/diffs/vs-run1`, { recursive: true })
for (const id of shared) {
  const e1 = m1.find((m) => m.id === id), e2 = m2.find((m) => m.id === id)
  const r = { id }
  // pixel
  const A = load(`${RUN1}/${e1.file}`), B = load(`${OUT}/${e2.file}`)
  r.pixel = diffPngs(A, B, `${OUT}/diffs/vs-run1/${id}.png`)
  if (e1.full && e2.full) {
    const FA = load(`${RUN1}/${e1.full}`), FB = load(`${OUT}/${e2.full}`)
    r.pixelFull = diffPngs(FA, FB, `${OUT}/diffs/vs-run1/${id}-full.png`)
    r.fullSize = { run1: `${FA.width}x${FA.height}`, run2: `${FB.width}x${FB.height}` }
  }
  // measure
  const a = rd(`${RUN1}/measure/${id}.json`), b = rd(`${OUT}/measure/${id}.json`)
  r.urlChanged = a.url !== b.url ? { run1: a.url, run2: b.url } : null
  r.scroll = { run1: { sh: a.scroll.scrollHeight, sw: a.scroll.scrollWidth }, run2: { sh: b.scroll.scrollHeight, sw: b.scroll.scrollWidth } }
  r.bodyText = a.bodyText !== b.bodyText ? { run1: a.bodyText, run2: b.bodyText } : null
  // interactive
  const ik = (e) => `${e.tag}|${e.name}`
  const ia = keyed(a.interactive, ik), ib = keyed(b.interactive, ik)
  r.interactive = { added: [], removed: [], changed: [] }
  for (const [k, e] of ib) if (!ia.has(k)) r.interactive.added.push({ name: e.name, tag: e.tag, own: e.ownRect, hit: e.effectiveHit, hasOnClick: e.hasOnClick })
  for (const [k, e] of ia) {
    if (!ib.has(k)) { r.interactive.removed.push({ name: e.name, tag: e.tag, own: e.ownRect, hit: e.effectiveHit, hasOnClick: e.hasOnClick }); continue }
    const f = ib.get(k)
    const ch = {}
    for (const rk of ['ownRect', 'unionRect', 'effectiveHit']) {
      if (!e[rk] || !f[rk]) { if (!!e[rk] !== !!f[rk]) ch[rk] = [e[rk], f[rk]]; continue }
      for (const dim of ['x', 'y', 'w', 'h']) {
        if (!same(e[rk][dim], f[rk][dim], rk === 'effectiveHit' ? 2.01 : 0.15)) (ch[rk] = ch[rk] || {})[dim] = [e[rk][dim], f[rk][dim]]
      }
    }
    for (const fk of ['hasOnClick', 'hotspotMarked', 'disabled', 'native']) if (e[fk] !== f[fk]) ch[fk] = [e[fk], f[fk]]
    if (Object.keys(ch).length) r.interactive.changed.push({ name: e.name, tag: e.tag, ...ch })
  }
  // texts
  const tk = (t) => t.text.slice(0, 80)
  const ta = keyed(a.texts, tk), tb = keyed(b.texts, tk)
  r.texts = { added: [], removed: [], changed: [] }
  for (const [k, t] of tb) if (!ta.has(k)) r.texts.added.push({ text: t.text.slice(0, 90), fontSize: t.fontSize, fontWeight: t.fontWeight, nominalRatio: t.nominalRatio, y: Math.round(t.rect[0].y * 10) / 10 })
  for (const [k, t] of ta) {
    if (!tb.has(k)) { r.texts.removed.push({ text: t.text.slice(0, 90), fontSize: t.fontSize, fontWeight: t.fontWeight, nominalRatio: t.nominalRatio, y: Math.round(t.rect[0].y * 10) / 10 }); continue }
    const u = tb.get(k)
    const ch = {}
    if (t.fontSize !== u.fontSize) ch.fontSize = [t.fontSize, u.fontSize]
    if (t.fontWeight !== u.fontWeight) ch.fontWeight = [t.fontWeight, u.fontWeight]
    if (t.color !== u.color) ch.color = [t.color, u.color]
    if (!same(t.nominalRatio, u.nominalRatio, 0.05)) ch.nominalRatio = [t.nominalRatio, u.nominalRatio]
    const ra = t.rect[0], rb = u.rect[0]
    for (const d of ['x', 'y', 'w', 'h']) if (!same(ra[d], rb[d], 0.6)) (ch.rect = ch.rect || {})[d] = [Math.round(ra[d] * 10) / 10, Math.round(rb[d] * 10) / 10]
    if (Object.keys(ch).length) r.texts.changed.push({ text: t.text.slice(0, 90), ...ch })
  }
  // aria
  const aa = fs.readFileSync(`${RUN1}/aria/${id}.txt`, 'utf8').split('\n'), ab = fs.readFileSync(`${OUT}/aria/${id}.txt`, 'utf8').split('\n')
  const sa = new Set(aa), sb = new Set(ab)
  r.aria = { linesOnlyRun1: aa.filter((l) => !sb.has(l)), linesOnlyRun2: ab.filter((l) => !sa.has(l)) }
  r.animations = { run1: a.animations.length, run2: b.animations.length }
  out.states[id] = r
}
fs.writeFileSync(`${OUT}/measure/run-comparison.json`, JSON.stringify(out, null, 1))
console.log('compared', shared.length, 'states; only in run 1:', out.onlyInRun1.join(',') || '-', '; only in run 2:', out.onlyInRun2.join(',') || '-')
